          <tbody>
            ${produtos.map(p => `
              <tr>
                <td style="font-size:24px">${p.imagem || '📦'}</td>
                <td>${p.nome}</td>
                <td>${p.departamento}</td>
                <td>${money(p.preco)}</td>
                <td>${p.estoque}</td>
